package builtin

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/edlitmus/halite/internal/exec"
	"github.com/edlitmus/halite/internal/value"
)

// **A second iptables.save of the same ruleset changes nothing** (issue
// 321, M-40). iptables-save stamps its output with the time, in a
// "# Generated by ... on <date>" line and a "# Completed on <date>" line,
// and save compared that whole text with the file, so every run wrote the
// file again and reported a change. Against a real iptables inside a
// throwaway network namespace; the pause makes the second stamp differ.
func TestLiveIPTablesSaveConverges(t *testing.T) {
	netnsReexec(t)
	r := New()
	c := &exec.Context{}
	path := filepath.Join(t.TempDir(), "rules.v4")
	save := func() bool {
		t.Helper()
		out, err := r.Exec.Call(c, "iptables.save", value.MapOf("path", path))
		if err != nil {
			t.Fatalf("iptables.save: %v", err)
		}
		changed, _ := out.(*value.Map).GetString("changed")
		return changed == true
	}
	if _, err := r.Exec.Call(c, "iptables.append", value.MapOf("chain", "INPUT", "rule", "-p tcp --dport 22 -j ACCEPT")); err != nil {
		t.Fatal(err)
	}
	if !save() {
		t.Fatal("the first save changed nothing")
	}
	first, _ := os.ReadFile(path)
	time.Sleep(1100 * time.Millisecond)
	if save() {
		second, _ := os.ReadFile(path)
		t.Errorf("a second save of the same ruleset reported a change\nfirst:\n%s\nsecond:\n%s", first, second)
	}

	// A real change is still a change.
	if _, err := r.Exec.Call(c, "iptables.append", value.MapOf("chain", "INPUT", "rule", "-p tcp --dport 443 -j ACCEPT")); err != nil {
		t.Fatal(err)
	}
	if !save() {
		t.Error("a save after a new rule changed nothing")
	}
	if b, _ := os.ReadFile(path); !strings.Contains(string(b), "--dport 443") {
		t.Errorf("the saved file does not hold the new rule:\n%s", b)
	}
}
